import{z as l,x as A,o as e,c as i,q as B,j as t,D as E,d as o,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"J 曲线","description":"","frontmatter":{"title":"J 曲线","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/j-curve.md","filePath":"econ/j-curve.md","lastUpdated":1791063341000}'),p={name:"econ/j-curve.md"};function d(h,a,C,c,_,D){const r=A("Mermaid");return e(),i("div",null,[a[2]||(a[2]=B('<h1 id="j-曲线" tabindex="-1">J 曲线 <a class="header-anchor" href="#j-曲线" aria-label="Permalink to &quot;J 曲线&quot;">​</a></h1><div class="epigraph"><p>贬值之后，贸易差额往往先恶化再改善：合同价格与数量一时粘住，计价效应抢在数量转换之前。</p><footer>—— Magee, Currency Contracts, Pass-through, and Devaluation, Brookings Papers on Economic Activity, 1973</footer></div><p><a href="/econ/marshall-lerner">上一课</a>给出贬值改善 \\(CA\\) 的弹性阈值。阈值是调整完成之后的比较静态。本课缺口是时间：短期数量粘住时，同一 \\(\\Delta e\\) 可以先把差额推向恶化，曲线像字母 J。不重推弹性公式，不把某国的月度贸易账画成谜。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>马歇尔–勒纳若成立，为什么政策上仍常见「贬了，逆差更大」？Magee（1973）把窗口拆成三段：货币合同期、pass-through 期、数量调整期。合同期里，已签的进出口按旧币种、旧数量执行，\\(E\\) 一动只改本币折算。若进口合同以外币计价，贬值立刻抬高本币进口账单，出口本币收入不一定同比例升——差额恶化，与长期弹性无关。</p><p>缺口因此不是再选一个阈值，而是：弹性条件在哪一段历史上还没有开始工作。蒙代尔下一课把 \\(NX(q)\\) 画成已经转换完成；本课声明那是终点，不是第一季度。</p><p><span class="marginnote">J 不是偏好形状。它是名义贬值后贸易差额对时间的路径：先下后上。上半支仍要求马歇尔–勒纳一类条件最终成立；否则曲线可以停在恶化段。</span></p><p><span class="marginnote">pass-through（汇率传递）可以翻译成「贬值的价签效应」：汇率变动有多大比例最终写进进口标价。数字感：本币贬 10%，进口价可能只涨 6%——剩下 4 个点被出口商的利润率吸收了，这就是「不完全传递」，它让数量转换的激励本身变弱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 Magee 的三段写成对价格与数量的不同粘性。合同期：数量与合同币种给定，只有折算。pass-through 期：新合同改价，数量仍慢。数量期：需求与供给沿弹性移动，马歇尔–勒纳开始发言。吸收与收入效应可以叠在三条路径上，\\(CA=S-I\\) 始终是恒等。</p>',10)),(e(),t(n,null,{default:E(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E8%B4%AC%E5%80%BC%22%5D%20--%3E%20CTR%5B%22%E5%90%88%E5%90%8C%E6%9C%9F%3A%20%E6%95%B0%E9%87%8F%E9%92%89%E6%AD%BB%22%5D%0A%20%20CTR%20--%3E%20DOWN%5B%22%E6%9C%AC%E5%B8%81%E5%B7%AE%E9%A2%9D%E6%81%B6%E5%8C%96%22%5D%0A%20%20DEV%20--%3E%20PT%5B%22%E4%BB%B7%E6%A0%BC%E9%80%90%E6%B8%90%E5%86%99%E5%85%A5%22%5D%0A%20%20PT%20--%3E%20QTY%5B%22%E6%95%B0%E9%87%8F%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20QTY%20--%3E%20UP%5B%22%E5%B7%AE%E9%A2%9D%E6%94%B9%E5%96%84%3A%20%E8%8B%A5%E5%BC%B9%E6%80%A7%E8%BF%87%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p>不要用某一季的逆差扩大否证马歇尔–勒纳：那可能仍在合同期。也不要用五年后的改善证明短窗里数量已经动了。</p><p><span class="marginnote">数字实例：贬值前 1 美元兑 6 元，进口 100 万美元的旧合同折 600 万元；汇率跳到 1 美元兑 7 元后，同一张合同立刻要付 700 万元。数量、单价都没动，纯折算就把账单推高约 17%——合同期的恶化就是这么来的。</span></p><h3 id="粘的是数量-不是会计" tabindex="-1">粘的是数量，不是会计 <a class="header-anchor" href="#粘的是数量-不是会计" aria-label="Permalink to &quot;粘的是数量，不是会计&quot;">​</a></h3><p>经常账户的记账不粘。粘的是合同、分销库存与生产计划。UIP 仍可以让 \\(E\\) 在资产市场立刻跳；货物的数量按另一套时钟走。这与多恩布什的「资产快、物价慢」同族，对象换成贸易量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是错开的名义刚性。已签合同把数量和计价货币锁在贬值之前；新价格传入零售与中间投入需要时间；厂商改出口供应、家庭改进口篮子更慢。于是计价效应（进口更贵）先到，支出转换后到。若 pass-through 不完全，价格激励本身也弱，J 的上半支更晚、更浅。</p>',6)),(e(),t(n,null,{default:E(()=>[s(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP_L%5B%22%E5%87%BA%E5%8F%A3%E4%BB%A5%E6%9C%AC%E5%B8%81%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20OUT%5B%22%E5%87%BA%E5%8F%A3%E6%9C%AC%E5%B8%81%E6%94%B6%E5%85%A5%E4%B8%8D%E5%8F%98%22%5D%0A%20%20IMP_F%5B%22%E8%BF%9B%E5%8F%A3%E4%BB%A5%E5%A4%96%E5%B8%81%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20BILL%5B%22%E6%9C%AC%E5%B8%81%E8%BF%9B%E5%8F%A3%E8%B4%A6%E5%8D%95%E4%B8%8A%E5%8D%87%22%5D%0A%20%20OUT%20--%3E%20WORSE%5B%22%E5%90%88%E5%90%8C%E6%9C%9F%E5%B7%AE%E9%A2%9D%E6%81%B6%E5%8C%96%3A%20%E6%9C%80%E4%B8%8D%E5%8F%8B%E5%A5%BD%E7%BB%84%E5%90%88%22%5D%0A%20%20BILL%20--%3E%20WORSE%0A%20%20EXP_F%5B%22%E5%87%BA%E5%8F%A3%E4%BB%A5%E5%A4%96%E5%B8%81%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20REVUP%5B%22%E6%8A%98%E7%AE%97%E5%90%8E%E6%9C%AC%E5%B8%81%E6%94%B6%E5%85%A5%E4%B8%8A%E5%8D%87%22%5D%0A%20%20IMP_L%5B%22%E8%BF%9B%E5%8F%A3%E4%BB%A5%E6%9C%AC%E5%B8%81%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20COST%5B%22%E8%BF%9B%E5%8F%A3%E6%88%90%E6%9C%AC%E4%B8%8D%E5%8F%98%22%5D%0A%20%20REVUP%20--%3E%20SOFT%5B%22%E5%90%88%E5%90%8C%E6%9C%9F%E6%81%B6%E5%8C%96%E8%BE%83%E8%BD%BB%22%5D%0A%20%20COST%20--%3E%20SOFT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p>长期相对 PPP 与中性仍是慢锚。J 曲线不否定锚，只说明过渡路径上 \\(NX\\) 的符号可以与长期导数相反。突然停止若同时砍吸收，差额可以立刻改善——那是 \\(S-I\\) 的吸收通道，不是本课的转换时钟。</p><p><span class="marginnote">计价货币选择会改合同期的符号：若出口以本币计价、进口以外币计价，贬值对合同期最不友好。这是 Magee 的合同算术，不是限价簿上的外汇订单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把每一条先下后上的贸易账都叫 J 曲线：还要有一次名义 \\(E\\) 的变动，以及合同/数量粘性这两件家具。也不要在此估计弹性或 pass-through。下一课 <a href="/econ/mundell-fleming">蒙代尔–弗莱明</a>把 \\(NX(q)\\) 放进 IS，默认用的是转换已经发生或正在发生的那一支。</p><p><span class="marginnote">常见误区：看到贬值后逆差先扩大，就断定马歇尔–勒纳不成立。实际上逆差扩大可能只是合同期的折算效应，弹性条件管的是数量调整完成之后的那一段。下结论前先问一句：现在是三段窗口里的哪一段。</span></p><p>后课默认：马歇尔–勒纳是终点条件；短窗可以恶化。资产平价的时钟快于货物数量的时钟。</p><p>实证弹性、汇率传递系数见货物与宏观实证，不在本栏重跑。外汇执行仍不进限价簿。</p><p>吸收同时砍时，差额可以立刻改善，看起来像没有 J。那是 \\(S-I\\) 的流量，不是数量已经转换。要把两条通道分开，才不会用危机年的顺差否证 Magee。</p><p>蒙代尔的 \\(NX(q)\\) 用的是转换已经发生或正在发生的那一支。把合同期的恶化画进 IS，会把短局乘数写成错误的符号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贬值后贸易差额可先恶化再改善：合同与数量粘住，计价效应先行。</li><li>Magee 把窗口拆成合同、传递、数量三段；马歇尔–勒纳管最后一段。</li><li>短窗恶化不自动否证长期弹性条件。</li><li>吸收通道与转换通道必须分开，才不会用危机顺差否证 J。</li><li>下一课蒙代尔把 \\(NX(q)\\) 放进 IS，用的是转换支而不是合同期。</li><li>出处：Magee, <em>BPEA</em> 1973；弹性阈值见上一课 Marshall、Lerner、Robinson。</li></ul>',11))])}const T=l(p,[["render",d]]);export{u as __pageData,T as default};
